<script>
  import { notEmpty } from '@splendidlabz/utils'
  import { getElement, resizeObserver } from '@splendidlabz/utils/dom'

  let klass = ''
  export { klass as class }
  export let breakpoints = {}

  let currentTarget = 'origin'
  let originalLocationRef = null
  let switcherooContentRef = null

  let _breakpoints = {}
  let shouldObserve = notEmpty(breakpoints)
  // TODO: Update Switcheroo to use createBreakpointArray

  // Converts user-provided breakpoints object into an array for easier internal usage. Currently only accept px breakpoint values.
  if (breakpoints) {
    shouldObserve = true
    _breakpoints = Object.entries(breakpoints).map(([key, value]) => {
      return { breakpoint: parseFloat(key), value }
    })
  }

  function observe(event) {
    const { entry } = event.detail
    const { width } = entry.contentRect
    if (!shouldObserve) return

    for (let i = _breakpoints.length - 1; i >= 0; i--) {
      const { breakpoint, value } = _breakpoints[i]
      const { target } = value
      if (width >= breakpoint) {
        if (currentTarget === target) break
        else {
          currentTarget = target
          switchTo(target)
        }
        break
      }
    }
  }

  export function switchTo(target) {
    // Place in origin
    if (target === 'origin') {
      originalLocationRef.appendChild(switcherooContentRef)
      return
    }

    // Place in target
    const targetElement = getElement(target)
    targetElement.appendChild(switcherooContentRef)
  }
</script>

<svelte:body
  use:resizeObserver={{ observe: shouldObserve }}
  on:resize={observe}
/>

<div
  class="Switcheroo {klass}"
  bind:this={originalLocationRef}
  {...$$restProps}
>
  <div class="SwitcherooContent" bind:this={switcherooContentRef}>
    <slot />
  </div>
</div>
